def calculate_perimeter_ratio(N):
    # Worst case connected shape: 1 x N strip
    P_N = 2 * N + 2
    return P_N / N

ratios = {}
for N in range(1, 11):
    ratio = calculate_perimeter_ratio(N)
    ratios[N] = ratio

print("N | P(N)/N")
for N, ratio in ratios.items():
    print(f"{N} | {ratio:.4f}")
